package dev.packeditor.core;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;

/** Writes the generated resource pack (a plain folder) from a Setup. */
public final class PackWriter {
    /** Resource pack formats for 26.1 (84) to 26.2 (88); the upper bound has headroom. */
    private static final String PACK_MCMETA = """
            {
              "pack": {
                "description": "Generated by Pack Editor. Do not edit - it is rewritten when you press Apply.",
                "min_format": 84,
                "max_format": 99
              }
            }
            """;

    private PackWriter() {}

    public record Result(int filesWritten, List<String> missing) {}

    /**
     * @param packDir the folder to (re)create; its name must be {@link UserPacks#GENERATED_NAME}
     */
    public static Result write(Path packDir, Setup setup, TextureSource vanilla, UserPacks packs) throws IOException {
        if (!packDir.getFileName().toString().equals(UserPacks.GENERATED_NAME)) {
            throw new IOException("refusing to write outside the generated pack folder");
        }
        deleteTree(packDir);
        Files.createDirectories(packDir);
        Files.writeString(packDir.resolve("pack.mcmeta"), PACK_MCMETA, StandardCharsets.UTF_8);

        int written = 0;
        List<String> missing = new ArrayList<>();
        for (Target t : Targets.ALL) {
            LookSpec look = setup.get(t.id());
            if (look.kind == LookSpec.Kind.VANILLA) continue;
            for (String path : t.paths()) {
                Optional<byte[]> src = Looks.source(path, look, vanilla, packs);
                if (src.isEmpty()) {
                    // pack didn't contain it (fine) or this game version has no such file
                    if (look.kind != LookSpec.Kind.PACK) missing.add(path);
                    continue;
                }
                byte[] outBytes;
                if (look.kind == LookSpec.Kind.PACK) {
                    outBytes = src.get();
                } else {
                    try {
                        outBytes = Png.write(Looks.apply(Png.read(src.get()), look));
                    } catch (IOException | RuntimeException e) {
                        missing.add(path + " (unreadable)");
                        continue;
                    }
                }
                Path out = packDir.resolve("assets/minecraft/" + path).normalize();
                if (!out.startsWith(packDir)) continue;
                Files.createDirectories(out.getParent());
                Files.write(out, outBytes);
                written++;

                Optional<byte[]> meta = look.kind == LookSpec.Kind.PACK
                        ? packs.read(look.pack, path + ".mcmeta")
                        : vanilla.vanillaMeta(path);
                if (meta.isPresent()) {
                    Files.write(packDir.resolve("assets/minecraft/" + path + ".mcmeta"), meta.get());
                }
            }
        }
        return new Result(written, missing);
    }

    static void deleteTree(Path root) throws IOException {
        if (!Files.exists(root)) return;
        try (var walk = Files.walk(root)) {
            List<Path> all = walk.sorted(Comparator.reverseOrder()).toList();
            for (Path p : all) Files.delete(p);
        }
    }
}
